"""Task-centric, integrity-checked context archives backed by SQLite."""

import hashlib
import json

from .domain import DomainError, now_iso


def _json(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _hash(value):
    return hashlib.sha256(_json(value).encode("utf-8")).hexdigest()


def _merge_messages(previous, rows):
    merged = [item for item in previous if item.get("role") == "user"]
    highlights = [item for item in previous if item.get("role") != "user"]
    positions = {(item["text"], item["status"]): item for item in merged}
    for row in rows:
        if row["role"] != "user":
            highlights.append(
                {
                    "text": row["content"][:256],
                    "source_refs": [row["id"]],
                    "status": "unverified",
                    "role": row["role"],
                    "omitted": len(row["content"]) > 256,
                }
            )
            continue
        key = (row["content"], "unverified")
        if key not in positions:
            item = {
                "text": row["content"],
                "source_refs": [],
                "status": "unverified",
                "role": "user",
                "omitted": False,
            }
            positions[key] = item
            merged.append(item)
        positions[key]["source_refs"].append(row["id"])
    return merged + highlights[-16:]


def _task_context(connection):
    quests = connection.execute(
        "SELECT * FROM quests WHERE conversation_id='main' AND status NOT IN ('completed','cancelled','failed') ORDER BY id LIMIT 101"
    ).fetchall()
    if len(quests) > 100:
        raise DomainError("Too many active Quests for safe compaction")
    result = []
    for quest in quests:
        qid = quest["id"]
        requirement = connection.execute(
            "SELECT * FROM quest_requirements WHERE quest_id=?", (qid,)
        ).fetchone()
        current_plan = connection.execute(
            "SELECT * FROM quest_plans WHERE quest_id=? AND revision=?",
            (qid, quest["plan_revision"]),
        ).fetchone()
        plan = (
            current_plan
            if current_plan
            and current_plan["approved_at"] is not None
            and current_plan["status"] in ("approved", "paused")
            else None
        )
        plan_state = "approved" if plan else "pending" if quest["plan_revision"] else "none"
        nodes = (
            connection.execute(
                "SELECT * FROM task_nodes WHERE plan_id=? ORDER BY node_key", (plan["id"],)
            ).fetchall()
            if plan
            else []
        )
        evidence = connection.execute(
            "SELECT id,kind,trusted,payload,created_at FROM evidence WHERE quest_id=? ORDER BY id",
            (qid,),
        ).fetchall()
        receipts = connection.execute(
            "SELECT r.id,r.execution_mode,r.result_digest,i.tool_name,i.resource_scope,i.plan_revision FROM action_receipts r JOIN action_intents i ON i.id=r.intent_id WHERE i.quest_id=? ORDER BY r.id",
            (qid,),
        ).fetchall()
        tasks = [
            {
                "key": node["node_key"],
                "objective": node["objective"],
                "success_criteria": json.loads(node["criteria_json"]),
                "status": node["status"],
                "expected_artifact": node["expected_artifact"],
                "allowed_tools": json.loads(node["allowed_tools"]),
                "evidence_refs": json.loads(node["evidence_refs"]),
            }
            for node in nodes
        ]
        result.append(
            {
                "quest_id": qid,
                "goal": quest["goal"],
                "status": quest["status"],
                "version": quest["version"],
                "source_refs": [f"quest:{qid}"],
                "success_criteria": json.loads(requirement["criteria_json"]) if requirement else [],
                "constraints": json.loads(quest["metadata"]),
                "plan_id": plan["id"] if plan else None,
                "plan_state": plan_state,
                "plan_revision": quest["plan_revision"],
                "pending_plan_id": current_plan["id"]
                if current_plan and not plan and current_plan["status"] == "proposed"
                else None,
                "decisions": [
                    {
                        "type": "approved_plan",
                        "source_refs": [f"plan:{plan['id']}"],
                        "digest": plan["digest"],
                    }
                ]
                if plan
                else [],
                "completed_steps": [node for node in tasks if node["status"] == "succeeded"],
                "pending_steps": [
                    node for node in tasks if node["status"] not in ("succeeded", "skipped")
                ],
                "blockers": [node for node in tasks if node["status"] == "blocked"],
                "artifacts": [
                    node["expected_artifact"] for node in tasks if node["expected_artifact"]
                ],
                "paths": [
                    receipt["resource_scope"]
                    for receipt in receipts
                    if receipt["plan_revision"] == quest["plan_revision"]
                ],
                "evidence_refs": [row["id"] for row in evidence if row["trusted"]],
                "facts": [
                    {
                        "statement": "Trusted evidence recorded",
                        "kind": row["kind"],
                        "source_refs": [f"evidence:{row['id']}"],
                    }
                    for row in evidence
                    if row["trusted"]
                ],
                "hypotheses": [
                    {
                        "statement": row["payload"],
                        "source_refs": [f"evidence:{row['id']}"],
                        "status": "unverified",
                    }
                    for row in evidence
                    if not row["trusted"]
                ],
                "receipts": [
                    {**dict(row), "historical": row["plan_revision"] != quest["plan_revision"]}
                    for row in receipts
                ],
            }
        )
    return result


class ContextService:
    def __init__(self, store):
        self.store = store

    @staticmethod
    def _through(connection, scope, scope_id):
        row = connection.execute(
            "SELECT through FROM context_archive_heads WHERE scope=? AND scope_id=?",
            (scope, scope_id),
        ).fetchone()
        return row["through"] if row else -1

    def _record_archive(self, connection, scope, scope_id, sources, capsule, through):
        inserted = connection.execute(
            "INSERT INTO context_archives(scope,scope_id,source_json,source_hash,capsule_json,capsule_hash,created_at) VALUES (?,?,?,?,?,?,?)",
            (
                scope,
                scope_id,
                _json(sources),
                _hash(sources),
                _json(capsule),
                _hash(capsule),
                now_iso(),
            ),
        )
        archive_id = inserted.lastrowid
        connection.executemany(
            "INSERT INTO context_archive_sources VALUES (?,?,?,?)",
            [(scope, scope_id, str(source["id"]), archive_id) for source in sources],
        )
        connection.execute(
            "INSERT INTO context_archive_heads VALUES (?,?,?,?) ON CONFLICT(scope,scope_id) DO UPDATE SET through=excluded.through,archive_id=excluded.archive_id",
            (scope, scope_id, through, archive_id),
        )

    def _verify_source(self, connection, scope, scope_id, source_id):
        index = connection.execute(
            "SELECT a.source_json,a.source_hash FROM context_archive_sources s JOIN context_archives a ON a.id=s.archive_id WHERE s.scope=? AND s.scope_id=? AND s.source_id=?",
            (scope, scope_id, str(source_id)),
        ).fetchone()
        if index is None:
            raise DomainError("Context source integrity failure")
        sources = json.loads(index["source_json"])
        if _hash(sources) != index["source_hash"]:
            raise DomainError("Context archive integrity failure")
        entry = next((item for item in sources if str(item["id"]) == str(source_id)), None)
        if scope == "router":
            current = connection.execute(
                "SELECT * FROM messages WHERE conversation_id=? AND id=?", (scope_id, source_id)
            ).fetchone()
        else:
            current = connection.execute(
                "SELECT * FROM worker_messages WHERE run_id=? AND ordinal=?", (scope_id, source_id)
            ).fetchone()
        if entry is None or current is None or _hash(dict(current)) != entry["hash"]:
            raise DomainError("Context source integrity failure")
        return current

    def router_snapshot(self):
        with self.store.connection() as connection:
            connection.execute("BEGIN")
            state = dict(
                connection.execute(
                    "SELECT * FROM router_state WHERE conversation_id='main'"
                ).fetchone()
            )
            through = self._through(connection, "router", "main")
            messages = [
                dict(row)
                for row in connection.execute(
                    "SELECT * FROM messages WHERE conversation_id='main' AND rowid>? ORDER BY rowid LIMIT 510",
                    (through,),
                )
            ]
            connection.commit()
        return {"state": state, "messages": messages}

    def _archives(self, connection, scope, scope_id):
        rows = connection.execute(
            "SELECT a.* FROM context_archive_heads h JOIN context_archives a ON a.id=h.archive_id WHERE h.scope=? AND h.scope_id=?",
            (scope, scope_id),
        ).fetchall()
        for row in rows:
            sources, capsule = json.loads(row["source_json"]), json.loads(row["capsule_json"])
            if _hash(sources) != row["source_hash"] or _hash(capsule) != row["capsule_hash"]:
                raise DomainError("Context archive integrity failure")
            refs = [
                ref for item in capsule.get("hypotheses", []) for ref in item.get("source_refs", [])
            ]
            refs += [
                ref
                for item in capsule.get("completed_steps", [])
                if isinstance(item, dict)
                for ref in item.get("source_refs", [])
            ]
            for ref in refs:
                self._verify_source(connection, scope, scope_id, ref)
        return rows

    def compact_router(self, *, keep_recent=10, snapshot=None):
        if keep_recent < 0:
            raise ValueError("keep_recent must be nonnegative")
        snapshot = snapshot or self.router_snapshot()
        with self.store.unit_of_work() as work:
            c = work.connection
            rows = self._archives(c, "router", "main")
            through = self._through(c, "router", "main")
            current = [
                dict(row)
                for row in c.execute(
                    "SELECT * FROM messages WHERE conversation_id='main' AND rowid>? ORDER BY rowid LIMIT 510",
                    (through,),
                )
            ]
            state = dict(
                c.execute("SELECT * FROM router_state WHERE conversation_id='main'").fetchone()
            )
            if current != snapshot["messages"] or state != snapshot["state"]:
                raise DomainError("Context changed concurrently")
            eligible = current[:-keep_recent] if keep_recent else current
            selected = eligible
            if not selected:
                return {"source_count": 0, "source_ids": []}
            previous = json.loads(rows[-1]["capsule_json"]) if rows else {}
            legacy = json.loads(state["capsule"] or "{}")
            quest_id = legacy.get("quest_id")
            quest = (
                c.execute("SELECT * FROM quests WHERE id=?", (quest_id,)).fetchone()
                if quest_id
                else None
            )
            requirements = (
                c.execute(
                    "SELECT criteria_json FROM quest_requirements WHERE quest_id=?", (quest_id,)
                ).fetchone()
                if quest_id
                else None
            )
            capsule = {
                "quest_id": quest_id,
                "goal": quest["goal"] if quest else legacy.get("goal", ""),
                "success_criteria": json.loads(requirements["criteria_json"])
                if requirements
                else legacy.get("success_criteria", []),
                "facts": previous.get("facts", []),
                # Preserve every user statement verbatim. It may contain an unstated
                # constraint; classify it as unverified rather than inventing facts.
                "hypotheses": _merge_messages(previous.get("hypotheses", []), selected),
                "decisions": previous.get("decisions", []),
                "completed_steps": previous.get("completed_steps", []),
                "pending_steps": previous.get("pending_steps", []),
                "blockers": previous.get("blockers", []),
                "constraints": legacy.get("constraints", previous.get("constraints", [])),
                "paths": previous.get("paths", []),
                "artifacts": previous.get("artifacts", []),
                "evidence_refs": previous.get("evidence_refs", []),
                "next_action": legacy.get("next_action", previous.get("next_action", "")),
                "source_event_cursor": state["event_cursor"],
                "tasks": _task_context(c),
            }
            sources = [{"id": row["id"], "hash": _hash(row)} for row in selected]
            boundary = c.execute(
                "SELECT rowid FROM messages WHERE id=?", (selected[-1]["id"],)
            ).fetchone()[0]
            self._record_archive(c, "router", "main", sources, capsule, boundary)
            changed = c.execute(
                "UPDATE router_state SET revision=revision+1 WHERE conversation_id='main' AND revision=? AND event_cursor=?",
                (state["revision"], state["event_cursor"]),
            )
            if changed.rowcount != 1:
                raise DomainError("Context changed concurrently")
            return {
                "source_count": len(sources),
                "source_ids": [source["id"] for source in sources],
            }

    def rebuild_router(self):
        with self.store.connection() as c:
            c.execute("BEGIN")
            rows = self._archives(c, "router", "main")
            through = self._through(c, "router", "main")
            messages = [
                dict(row)
                for row in c.execute(
                    "SELECT * FROM messages WHERE conversation_id='main' AND rowid>? ORDER BY rowid LIMIT 5001",
                    (through,),
                )
            ]
            capsule = json.loads(rows[-1]["capsule_json"]) if rows else {}
            if capsule:
                capsule["tasks"] = _task_context(c)
                task = next(
                    (
                        item
                        for item in capsule["tasks"]
                        if item["quest_id"] == capsule.get("quest_id")
                    ),
                    None,
                )
                if task:
                    capsule["goal"] = task["goal"]
                    capsule["success_criteria"] = task["success_criteria"]
                elif capsule.get("quest_id"):
                    capsule["goal"], capsule["success_criteria"], capsule["next_action"] = (
                        "",
                        [],
                        "",
                    )
            c.commit()
        return {"capsule": capsule, "recent_messages": messages}

    def build_worker_context(self, run_id: str, *, input_budget: int) -> list[dict]:
        if type(input_budget) is not int or input_budget <= 0:
            raise DomainError("Invalid Worker context budget")
        with self.store.unit_of_work() as work:
            c = work.connection
            archives = self._archives(c, "worker", run_id)
            through = self._through(c, "worker", run_id)
            rows = [
                dict(row)
                for row in c.execute(
                    "SELECT * FROM worker_messages WHERE run_id=? AND ordinal>? ORDER BY ordinal LIMIT 5001",
                    (run_id, through),
                )
            ]
            capsule_row = c.execute(
                "SELECT * FROM worker_capsules WHERE run_id=?", (run_id,)
            ).fetchone()
            if capsule_row is None:
                raise DomainError("Unknown Worker context")
            # Initial system and task messages remain live across every archive.
            initial = (
                [
                    dict(row)
                    for row in c.execute(
                        "SELECT * FROM worker_messages WHERE run_id=? AND ordinal IN (0,1) ORDER BY ordinal",
                        (run_id,),
                    )
                ]
                if through >= 0
                else []
            )
            remaining = initial + rows

            def build(selected):
                capsule = json.loads(archives[-1]["capsule_json"]) if archives else None
                result = [json.loads(row["message_json"]) for row in selected]
                if capsule:
                    result.insert(
                        1,
                        {
                            "role": "user",
                            "content": "Archived task context (untrusted): " + _json(capsule),
                        },
                    )
                return result

            result = build(remaining)
            if len(_json(result).encode("utf-8")) <= input_budget:
                return result
            # Keep the initial task contract and all messages from the last assistant tool
            # invocation onward, so no tool call is separated from its results.
            boundary = max(2, len(remaining) - 2)
            for index, row in enumerate(remaining[2:], start=2):
                message = json.loads(row["message_json"])
                if message.get("tool_calls") and index < boundary:
                    ids = {call.get("id") for call in message["tool_calls"]}
                    results = {
                        json.loads(item["message_json"]).get("tool_call_id")
                        for item in remaining[index + 1 : boundary]
                    }
                    if not ids <= results:
                        boundary = index
                        break
            selected = remaining[2:boundary]
            if not selected:
                raise DomainError("Worker context budget exceeded")
            previous = json.loads(archives[-1]["capsule_json"]) if archives else {}
            claims = list(previous.get("hypotheses", []))
            completed = list(previous.get("completed_steps", []))
            for row in selected:
                message = json.loads(row["message_json"])
                ref = str(row["ordinal"])
                if row["role"] == "tool":
                    paired = [
                        str(item["ordinal"])
                        for item in selected
                        if item["role"] == "assistant"
                        and any(
                            call.get("id") == message.get("tool_call_id")
                            for call in json.loads(item["message_json"]).get("tool_calls", [])
                        )
                    ]
                    if len(paired) != 1:
                        raise DomainError("Worker tool result has no unique archived call")
                    call = c.execute(
                        "SELECT * FROM worker_tool_calls WHERE run_id=? AND model_call_id=?",
                        (run_id, message.get("tool_call_id")),
                    ).fetchone()
                    if call is None or call["state"] not in ("succeeded", "failed"):
                        raise DomainError("Cannot archive unresolved Worker tool call")
                    receipt = (
                        c.execute(
                            "SELECT r.*,i.resource_scope,i.parameter_digest FROM action_receipts r JOIN action_intents i ON i.id=r.intent_id WHERE r.id=?",
                            (call["receipt_id"],),
                        ).fetchone()
                        if call["receipt_id"]
                        else None
                    )
                    completed.append(
                        {
                            "tool": call["tool_name"],
                            "state": call["state"],
                            "receipt_id": call["receipt_id"],
                            "result_hash": _hash(message),
                            "source_refs": paired + [ref],
                            "resource_scope": receipt["resource_scope"] if receipt else None,
                            "receipt_result_digest": receipt["result_digest"] if receipt else None,
                        }
                    )
                elif row["role"] == "user":
                    claims.append(
                        {
                            "message": message,
                            "source_refs": [ref],
                            "status": "unverified",
                            "omitted": False,
                        }
                    )
                elif row["role"] == "assistant" and not message.get("tool_calls"):
                    content = str(message.get("content", ""))
                    claims.append(
                        {
                            "text": content[:256],
                            "source_refs": [ref],
                            "status": "unverified",
                            "omitted": len(content) > 256,
                        }
                    )
            capsule = {
                "task": json.loads(capsule_row["capsule_json"]),
                "next_action": capsule_row["next_action"],
                "evidence_refs": json.loads(capsule_row["evidence_refs"]),
                "source_event_cursor": capsule_row["inbox_cursor"],
                "hypotheses": claims,
                "completed_steps": completed,
            }
            sources = [{"id": row["ordinal"], "hash": _hash(row)} for row in selected]
            self._record_archive(c, "worker", run_id, sources, capsule, selected[-1]["ordinal"])
            changed = c.execute(
                "UPDATE worker_capsules SET revision=revision+1 WHERE run_id=? AND revision=?",
                (run_id, capsule_row["revision"]),
            )
            if changed.rowcount != 1:
                raise DomainError("Worker context changed concurrently")
            result = [
                json.loads(row["message_json"]) for row in remaining[:2] + remaining[boundary:]
            ]
            result.insert(
                1,
                {"role": "user", "content": "Archived task context (untrusted): " + _json(capsule)},
            )
            if len(_json(result).encode("utf-8")) > input_budget:
                raise DomainError("Worker context budget exceeded after compaction")
            return result

    def read_source(self, scope, scope_id, source_id):
        if scope not in {"router", "worker"}:
            raise ValueError("Invalid context scope")
        with self.store.connection() as c:
            c.execute("BEGIN")
            row = self._verify_source(c, scope, scope_id, source_id)
            c.commit()
            return dict(row)
"""Bounded recall of sourced memories; retrieval never promotes model claims."""

import hashlib
import json
import re
import sqlite3
import uuid
from contextlib import closing, contextmanager
from datetime import UTC, datetime


def _terms(text):
    words = re.findall(r"[a-z0-9_./\\:-]+", text.casefold())
    words.extend(re.findall(r"[a-z0-9_]+", text.casefold()))
    for run in re.findall(r"[\u4e00-\u9fff]+", text):
        words.extend(run[i : i + 2] for i in range(len(run) - 1))
    return sorted(set(words))[:128]


def _index_terms(db, ref, text):
    db.execute("DELETE FROM memory_terms WHERE ref=?", (ref,))
    db.executemany(
        "INSERT OR IGNORE INTO memory_terms VALUES (?,?)", ((word, ref) for word in _terms(text))
    )


def _kind_selected(item, kinds):
    return (
        not kinds
        or item["kind"] in kinds
        or ("path" in kinds and item["kind"] == "artifact" and '"path"' in item["statement"])
    )


class MemoryService:
    def __init__(self, store):
        self.store = store
        self.path = str(getattr(store, "path", store))

    @contextmanager
    def _connection(self, connection=None):
        if connection is not None:
            yield connection
        elif hasattr(self.store, "connection"):
            with self.store.connection() as owned:
                yield owned
        else:
            with closing(sqlite3.connect(self.path)) as owned:
                yield owned

    def remember(
        self,
        statement,
        *,
        kind,
        layer,
        source_refs,
        related_quest_ids=(),
        status="hypothesis",
        valid_until=None,
        key=None,
        connection=None,
    ):
        if (
            not isinstance(statement, str)
            or not statement.strip()
            or len(statement.encode()) > 8192
        ):
            raise ValueError("Invalid memory statement")
        if layer not in {"L0", "L1", "L2", "L3"} or status not in {
            "hypothesis",
            "confirmed",
            "invalid",
        }:
            raise ValueError("Invalid memory layer or status")
        if status == "confirmed":
            raise ValueError("Confirmed facts require a Core-derived source")
        if kind not in {
            "task",
            "project",
            "path",
            "artifact",
            "decision",
            "failure",
            "fact",
            "constraint",
        }:
            raise ValueError("Invalid memory kind")
        refs = list(source_refs)
        quests = list(related_quest_ids)
        if (
            not refs
            or len(refs) > 32
            or len(quests) > 32
            or any(not isinstance(x, str) or not x or len(x) > 512 for x in refs + quests)
        ):
            raise ValueError("Memory requires bounded source references and Quest IDs")
        if valid_until is not None:
            expiry = datetime.fromisoformat(valid_until)
            if expiry.tzinfo is None:
                raise ValueError("Expiry must include timezone")
            valid_until = expiry.astimezone(UTC).isoformat()
        if key is not None and (not isinstance(key, str) or not key or len(key) > 512):
            raise ValueError("Invalid memory key")
        item_id = uuid.uuid4().hex
        with self._connection(connection) as db:
            db.execute(
                "INSERT INTO memories VALUES (?,?,?,?,?,?,?,?,?,?)",
                (
                    item_id,
                    statement,
                    kind,
                    layer,
                    status,
                    json.dumps(refs, ensure_ascii=False),
                    datetime.now(UTC).isoformat(),
                    valid_until,
                    json.dumps(quests, ensure_ascii=False),
                    key,
                ),
            )
            _index_terms(
                db, f"memory:{item_id}", " ".join([statement, kind, key or "", *refs, *quests])
            )
            if connection is None:
                db.commit()
        return item_id

    def revoke_source(self, source_ref, *, connection=None):
        if not isinstance(source_ref, str) or not source_ref:
            raise ValueError("Invalid source reference")
        with self._connection(connection) as db:
            db.execute("INSERT OR IGNORE INTO revoked_memory_sources VALUES (?)", (source_ref,))
            if connection is None:
                db.commit()

    def invalidate(self, memory_id, *, connection=None):
        """Invalidate a record without erasing its provenance."""
        with self._connection(connection) as db:
            changed = db.execute(
                "UPDATE memories SET status='invalid' WHERE id=?", (memory_id,)
            ).rowcount
            if connection is None:
                db.commit()
        return bool(changed)

    def sync_sources(self, *, connection=None):
        """Index at most 256 rows per source per call within the caller transaction."""
        with self._connection(connection) as db:
            if connection is None:
                db.execute("BEGIN IMMEDIATE")
            event_cursor, quest_cursor, evidence_cursor = db.execute(
                "SELECT event_seq,quest_rowid,evidence_rowid FROM memory_source_cursor WHERE singleton=1"
            ).fetchone()

            def upsert(ref, quest, revision, source_type, trust, snapshot):
                encoded = json.dumps(
                    snapshot, ensure_ascii=False, sort_keys=True, separators=(",", ":")
                )
                digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
                db.execute(
                    """INSERT INTO memory_source_index VALUES (?,?,?,?,?,?,?,1)
                    ON CONFLICT(source_ref) DO UPDATE SET source_hash=excluded.source_hash,
                    quest_id=excluded.quest_id,plan_revision=excluded.plan_revision,
                    source_type=excluded.source_type,trust=excluded.trust,snapshot=excluded.snapshot,
                    active=1""",
                    (ref, digest, quest, revision, source_type, trust, encoded),
                )
                _index_terms(db, ref, f"{encoded} {source_type} {quest} {ref}")

            workspace = (
                db.execute("SELECT id,root FROM workspace WHERE singleton=1").fetchone()
                if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND name='workspace'"
                ).fetchone()
                else None
            )
            if workspace:
                upsert(
                    f"workspace:{workspace[0]}",
                    "",
                    None,
                    "project",
                    "core_workspace",
                    {"id": workspace[0], "root": workspace[1]},
                )

            new_quests = db.execute(
                "SELECT rowid,id FROM quests WHERE rowid>? ORDER BY rowid LIMIT 256",
                (quest_cursor,),
            ).fetchall()
            events = db.execute(
                "SELECT seq,id,event_type,quest_id,payload,created_at FROM events WHERE seq>? ORDER BY seq LIMIT 256",
                (event_cursor,),
            ).fetchall()
            evidence = db.execute(
                "SELECT rowid,id,quest_id,kind,trusted,payload,created_at FROM evidence WHERE rowid>? ORDER BY rowid LIMIT 256",
                (evidence_cursor,),
            ).fetchall()
            affected = {row[1] for row in new_quests}
            affected.update(row[3] for row in events if row[3])
            affected.update(row[2] for row in evidence if row[2])
            revisions = {}
            for quest_id in sorted(affected):
                row = db.execute(
                    "SELECT title,goal,created_at,plan_revision FROM quests WHERE id=?", (quest_id,)
                ).fetchone()
                if not row:
                    continue
                title, goal, created, revision = row
                revisions[quest_id] = revision
                upsert(
                    f"quest:{quest_id}",
                    quest_id,
                    revision,
                    "quest",
                    "core_record",
                    {"title": title, "goal": goal, "created_at": created},
                )
                db.execute(
                    "UPDATE memory_source_index SET active=0 WHERE quest_id=? AND source_type!='quest' AND plan_revision IS NOT NULL AND plan_revision!=?",
                    (quest_id, revision),
                )
            event_types = {
                "approval.decided",
                "quest.plan_approved",
                "worker.failed",
                "worker.blocked",
                "tool.execution_uncertain",
                "evidence.json_checked",
                "evidence.artifact_verified",
            }
            for seq, event_id, event_type, quest_id, payload, created in events:
                if event_type not in event_types or quest_id not in revisions:
                    continue
                data = json.loads(payload)
                revision = data.get("plan_revision")
                # Resolve references against Core-owned records, never infer the
                # event's old revision from the Quest's current revision.
                for field, table, column in (
                    ("plan_id", "quest_plans", "revision"),
                    ("approval_id", "approvals", "plan_revision"),
                    ("intent_id", "action_intents", "plan_revision"),
                    ("run_id", "execution_runs", "plan_revision"),
                ):
                    if revision is not None or not data.get(field):
                        continue
                    if not db.execute(
                        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)
                    ).fetchone():
                        continue
                    source = db.execute(
                        f"SELECT {column} FROM {table} WHERE id=? AND quest_id=?",
                        (data[field], quest_id),
                    ).fetchone()
                    if source:
                        revision = source[0]
                if type(revision) is not int:
                    continue
                upsert(
                    f"event:{event_id}",
                    quest_id,
                    revision,
                    event_type,
                    "core_event",
                    {"payload": data, "created_at": created},
                )
                if revision != revisions[quest_id]:
                    db.execute(
                        "UPDATE memory_source_index SET active=0 WHERE source_ref=?",
                        (f"event:{event_id}",),
                    )
            for _, evidence_id, quest_id, kind, trusted, payload, created in evidence:
                if not trusted or quest_id not in revisions:
                    continue
                data = json.loads(payload)
                revision = data.get("plan_revision")
                if revision is not None and type(revision) is not int:
                    continue
                upsert(
                    f"evidence:{evidence_id}",
                    quest_id,
                    revision,
                    kind,
                    "verified_evidence",
                    {"payload": data, "created_at": created},
                )
                if revision is not None and revision != revisions[quest_id]:
                    db.execute(
                        "UPDATE memory_source_index SET active=0 WHERE source_ref=?",
                        (f"evidence:{evidence_id}",),
                    )
            for quest_id in affected:
                db.execute(
                    """UPDATE memory_source_index SET active=0 WHERE quest_id=?
                    AND source_ref IN (SELECT source_ref FROM revoked_memory_sources)""",
                    (quest_id,),
                )
            db.execute(
                "UPDATE memory_source_cursor SET event_seq=?,quest_rowid=?,evidence_rowid=? WHERE singleton=1",
                (
                    events[-1][0] if events else event_cursor,
                    new_quests[-1][0] if new_quests else quest_cursor,
                    evidence[-1][0] if evidence else evidence_cursor,
                ),
            )
            if connection is None:
                db.commit()
            return {
                "event_seq": events[-1][0] if events else event_cursor,
                "has_more": len(events) == 256 or len(new_quests) == 256 or len(evidence) == 256,
            }

    def retrieve_context(
        self,
        query,
        quest_ids=(),
        source_refs=(),
        limit=20,
        max_bytes=16384,
        connection=None,
        cursor=None,
        kinds=(),
        layers=(),
    ):
        """Read at most 512 indexed candidates; cursor continues in stable ref order."""
        if not isinstance(query, str) or len(query.encode()) > 8192:
            raise ValueError("Invalid query")
        if not 1 <= limit <= 100 or not 0 <= max_bytes <= 65536:
            raise ValueError("Invalid recall bounds")
        quests, refs = list(quest_ids), list(source_refs)
        kinds, layers = set(kinds), set(layers)
        if len(kinds) > 16 or len(layers) > 4:
            raise ValueError("Invalid recall filters")
        if (
            len(quests) > 32
            or len(refs) > 32
            or any(
                not isinstance(value, str) or not value or len(value) > 512
                for value in quests + refs
            )
        ):
            raise ValueError("Invalid recall selectors")
        if cursor is not None and (not isinstance(cursor, str) or len(cursor) > 600):
            raise ValueError("Invalid recall cursor")
        words = _terms(" ".join([query, *quests, *refs]))
        if not words and not quests and not refs:
            return {"items": [], "omitted": 0, "bytes": 0, "cursor": None}
        items, used, omitted, next_cursor = [], 2, 0, None
        now = datetime.now(UTC)
        with self._connection(connection) as db:
            # Bound each indexed range independently; a popular term cannot force
            # an unbounded DISTINCT/sort over the entire database.
            candidate_set = set()
            for word in words:
                candidate_set.update(
                    row[0]
                    for row in db.execute(
                        "SELECT ref FROM memory_terms WHERE term=? AND ref>? ORDER BY ref LIMIT 513",
                        (word, cursor or ""),
                    )
                )
            for quest_id in quests:
                candidate_set.update(
                    row[0]
                    for row in db.execute(
                        "SELECT source_ref FROM memory_source_index WHERE quest_id=? AND active=1 AND source_ref>? ORDER BY source_ref LIMIT 513",
                        (quest_id, cursor or ""),
                    )
                )
            candidate_set.update(ref for ref in refs if ref > (cursor or ""))
            candidates = sorted(candidate_set)[:513]
            previous = cursor or ""
            for position, ref in enumerate(candidates[:512]):
                if len(items) >= limit:
                    omitted += len(candidates) - position
                    next_cursor = next_cursor or previous
                    break
                previous = ref
                item = None
                if ref.startswith("memory:"):
                    row = db.execute(
                        "SELECT id,statement,kind,layer,status,source_refs,created_at,valid_until,related_quest_ids,memory_key FROM memories WHERE id=?",
                        (ref[7:],),
                    ).fetchone()
                    if not row:
                        continue
                    (
                        ident,
                        statement,
                        kind,
                        layer,
                        status,
                        raw_refs,
                        created,
                        expiry,
                        raw_quests,
                        key,
                    ) = row
                    item_refs, item_quests = json.loads(raw_refs), json.loads(raw_quests)
                    if status == "invalid" or (expiry and datetime.fromisoformat(expiry) <= now):
                        continue
                    if any(
                        db.execute(
                            "SELECT 1 FROM revoked_memory_sources WHERE source_ref=?", (source,)
                        ).fetchone()
                        for source in item_refs
                    ):
                        continue
                    conflict = False
                    if key:
                        others = db.execute(
                            "SELECT statement,valid_until,source_refs FROM memories WHERE memory_key=? AND status!='invalid' AND id!=? LIMIT 101",
                            (key, ident),
                        ).fetchall()
                        conflict = len(others) > 100
                        for other_statement, other_expiry, other_refs in others[:100]:
                            if other_expiry and datetime.fromisoformat(other_expiry) <= now:
                                continue
                            if any(
                                db.execute(
                                    "SELECT 1 FROM revoked_memory_sources WHERE source_ref=?",
                                    (source,),
                                ).fetchone()
                                for source in json.loads(other_refs)
                            ):
                                continue
                            if other_statement != statement:
                                conflict = True
                                break
                    item = {
                        "id": ident,
                        "statement": statement,
                        "kind": kind,
                        "layer": layer,
                        "status": status,
                        "source_refs": item_refs,
                        "created_at": created,
                        "valid_until": expiry,
                        "related_quest_ids": item_quests,
                        "key": key,
                        "freshness": "unexpired" if expiry else "unknown",
                        "conflicted": conflict,
                    }
                else:
                    row = db.execute(
                        "SELECT source_hash,quest_id,plan_revision,source_type,trust,snapshot,active FROM memory_source_index WHERE source_ref=?",
                        (ref,),
                    ).fetchone()
                    if (
                        not row
                        or not row[6]
                        or db.execute(
                            "SELECT 1 FROM revoked_memory_sources WHERE source_ref=?", (ref,)
                        ).fetchone()
                    ):
                        continue
                    digest, quest_id, revision, source_type, trust, snapshot, _ = row
                    if hashlib.sha256(snapshot.encode("utf-8")).hexdigest() != digest:
                        continue
                    if trust == "core_workspace":
                        workspace = db.execute(
                            "SELECT id,root FROM workspace WHERE singleton=1"
                        ).fetchone()
                        if not workspace or json.loads(snapshot) != {
                            "id": workspace[0],
                            "root": workspace[1],
                        }:
                            continue
                        item = {
                            "id": ref,
                            "statement": f"workspace {workspace[0]}: {workspace[1]}",
                            "kind": "project",
                            "layer": "L2",
                            "status": "hypothesis",
                            "source_refs": [ref],
                            "created_at": None,
                            "valid_until": None,
                            "related_quest_ids": [],
                            "key": None,
                            "freshness": "current",
                            "conflicted": False,
                            "source_hash": digest,
                            "source_type": trust,
                        }
                    else:
                        item = None
                    if item is not None:
                        if not _kind_selected(item, kinds) or (
                            layers and item["layer"] not in layers
                        ):
                            continue
                        size = len(
                            json.dumps(item, ensure_ascii=False, separators=(",", ":")).encode(
                                "utf-8"
                            )
                        ) + bool(items)
                        if used + size > max_bytes:
                            omitted += 1
                            continue
                        items.append(item)
                        used += size
                        continue
                    current = db.execute(
                        "SELECT title,goal,created_at,plan_revision FROM quests WHERE id=?",
                        (quest_id,),
                    ).fetchone()
                    if not current or (
                        source_type != "quest" and revision is not None and revision != current[3]
                    ):
                        continue
                    expected = None
                    if trust == "core_record":
                        expected = {
                            "title": current[0],
                            "goal": current[1],
                            "created_at": current[2],
                        }
                        statement, kind, created = f"{current[0]}: {current[1]}", "task", current[2]
                    elif trust == "core_event":
                        event = db.execute(
                            "SELECT event_type,payload,created_at FROM events WHERE id=? AND quest_id=?",
                            (ref[6:], quest_id),
                        ).fetchone()
                        if event and event[0] == source_type:
                            event_data = json.loads(event[1])
                            if source_type == "approval.decided" and event_data.get("approval_id"):
                                approval = db.execute(
                                    "SELECT status FROM approvals WHERE id=? AND quest_id=?",
                                    (event_data["approval_id"], quest_id),
                                ).fetchone()
                                if not approval or approval[0] != event_data.get("status"):
                                    continue
                            expected = {"payload": event_data, "created_at": event[2]}
                            statement, created = f"{source_type}: {event[1]}", event[2]
                            kind = (
                                "failure"
                                if source_type
                                in {"worker.failed", "worker.blocked", "tool.execution_uncertain"}
                                else (
                                    "decision"
                                    if source_type in {"approval.decided", "quest.plan_approved"}
                                    else "artifact"
                                )
                            )
                    elif trust == "verified_evidence":
                        evidence = db.execute(
                            "SELECT kind,payload,created_at FROM evidence WHERE id=? AND quest_id=? AND trusted=1",
                            (ref[9:], quest_id),
                        ).fetchone()
                        if evidence and evidence[0] == source_type:
                            expected = {
                                "payload": json.loads(evidence[1]),
                                "created_at": evidence[2],
                            }
                            statement, created = f"{source_type}: {evidence[1]}", evidence[2]
                            kind = "artifact" if source_type == "artifact" else "fact"
                    if (
                        expected is None
                        or json.loads(snapshot) != expected
                        or len(statement.encode()) > 8192
                    ):
                        continue
                    item = {
                        "id": ref,
                        "statement": statement,
                        "kind": kind,
                        "layer": "L3" if kind == "failure" else "L1",
                        "status": "hypothesis",
                        "source_refs": [ref],
                        "created_at": created,
                        "valid_until": None,
                        "related_quest_ids": [quest_id],
                        "key": None,
                        "freshness": "current" if trust == "core_record" else "historical",
                        "conflicted": False,
                        "source_hash": digest,
                        "source_type": trust,
                        "plan_binding": "unbound" if revision is None else "bound",
                        "trust_scope": "source record only; no domain truth or current artifact validation",
                    }
                if not _kind_selected(item, kinds) or (layers and item["layer"] not in layers):
                    continue
                size = len(
                    json.dumps(item, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
                ) + bool(items)
                if used + size > max_bytes:
                    omitted += 1
                    continue
                items.append(item)
                used += size
            if len(candidates) > 512:
                next_cursor = next_cursor or candidates[511]
                omitted += 1
        return {
            "items": items,
            "omitted": omitted,
            "bytes": used if items else 0,
            "cursor": next_cursor,
        }

