const validation = "$ErrorActionPreference='Stop'
$phase2DocFiles=@('README.md','docs/STATUS.md','docs/QUALITY_GATES.md','docs/ROADMAP.md','docs/PHASE2_AGENT_INTELLIGENCE_REPORT.md','docs/PHASE2_EXPERIMENTS.md','docs/PHASE2_STATUS.md','docs/adr/ADR-009-agent-intelligence-contracts-and-review.md','docs/audit/phase2/execution-chain-audit.md')
$phase2StrictUtf8=[Text.UTF8Encoding]::new($false,$true)
$phase2DocProblems=[Collections.Generic.List[string]]::new()
$phase2LocalLinkCount=0
foreach($phase2Doc in $phase2DocFiles){
 $phase2Absolute=(Resolve-Path -LiteralPath $phase2Doc).Path
 $phase2Text=$phase2StrictUtf8.GetString([IO.File]::ReadAllBytes($phase2Absolute))
 if([regex]::IsMatch($phase2Text,'(?m)[ \t]+\r?$')){$phase2DocProblems.Add('Trailing whitespace: '+$phase2Doc)}
 foreach($phase2Match in [regex]::Matches($phase2Text,'!?\[[^\]]*\]\((?<target>[^)]+)\)')){
  $phase2Target=$phase2Match.Groups['target'].Value.Trim('<','>')
  if($phase2Target -match '^[A-Za-z][A-Za-z0-9+.-]*:' -or $phase2Target.StartsWith('#')){continue}
  $phase2Target=[Uri]::UnescapeDataString(($phase2Target -split '#',2)[0])
  if(-not $phase2Target){continue}
  $phase2LocalLinkCount++
  $phase2Resolved=Join-Path ([IO.Path]::GetDirectoryName($phase2Absolute)) $phase2Target
  if(-not (Test-Path -LiteralPath $phase2Resolved)){$phase2DocProblems.Add('Missing local link: '+$phase2Doc+' -> '+$phase2Target)}
 }
}
if($phase2DocProblems.Count){$phase2DocProblems;exit 1}
Write-Output ('Validated '+$phase2DocFiles.Count+' UTF-8 documents, '+$phase2LocalLinkCount+' local links, no trailing whitespace.')
";
store("phase2DocValidation",validation);
text(await tools.exec_command({cmd:validation,max_output_tokens:2200}));

